export async function continueChat(model, history, userText, { customerId }) {
  const messages = [...history, { role: 'user', content: userText }];
  const result = await generateText({
    model,
    system: ORDER_RULES,
    tools: { orderLookup },
    experimental_context: { customerId },
    maxSteps: 4,
    messages,
  });

  const newMessages = [];

  // Reconstruct messages from each step
  for (const step of result.steps || []) {
    if (step.toolCalls && step.toolCalls.length > 0) {
      // Add assistant message with tool calls
      newMessages.push({
        role: 'assistant',
        content: step.toolCalls.map(tc => ({
          type: 'tool-use',
          id: tc.toolCallId,
          name: tc.toolName,
          input: typeof tc.input === 'string' ? JSON.parse(tc.input) : tc.input,
        })),
      });

      // Add tool result messages if they exist in the step
      if (step.toolResults && step.toolResults.length > 0) {
        for (const tr of step.toolResults) {
          newMessages.push({
            role: 'user',
            content: [{
              type: 'tool-result',
              toolUseId: tr.toolCallId,
              content: typeof tr.result === 'string'
                ? tr.result
                : JSON.stringify(tr.result),
            }],
          });
        }
      }
    }
  }

  // Add final assistant message
  newMessages.push({
    role: 'assistant',
    content: result.text,
  });

  return [...messages, ...newMessages];
}

